import sys, json, re
txt=open(sys.argv[1]).read()
blocks=re.findall(r"```json\n(.*?)\n```", txt, re.S)
heads=re.findall(r"^## (.+)$", txt, re.M)
for h,b in zip(heads, blocks):
    try: data=json.loads(b)
    except Exception as e: print(h, "PARSE FAIL", e); continue
    if h.startswith("Your words"):
        print("== YOUR WORDS =="); [print(" ", d.get("date"), "|", d.get("title"), "|", (d.get("text") or "")[:120].replace("\n"," ")) for d in data]
    elif h.startswith("Roadmap"):
        print("== ROADMAP (live, by priority) ==")
        for d in sorted(data, key=lambda d: -(d.get("priority") or 0)):
            print(" ", d.get("priority"), "|", d.get("id"), "|", d.get("title"), "|", (d.get("details") or "")[:90].replace("\n"," "))
    elif h.startswith("Amendments"):
        print("== AMENDMENTS since 2026-09-25 ==")
        for d in data:
            if (d.get("date") or "") >= "2026-09-25":
                req=d.get("request") or {}
                print(" ", d.get("date"), "|", d.get("kind"), "|", req.get("title") or d.get("title"), "|", (d.get("text") or "")[:160].replace("\n"," "))
EOF",
